command:
$files = @('.forge-codex/state/decisions/P16-009-bounded-dashboard-adapters-execution-and-deadlines.md','include/ForgeConductor/Infrastructure/Windows/WindowsDashboardDeadlineScheduler.h','src/Infrastructure/Windows/WindowsDashboardDeadlineScheduler.cpp','tests/Dashboard/WindowsDashboardDeadlineSchedulerTests.cpp')
$utf8 = [Text.UTF8Encoding]::new($false, $true)
foreach ($file in $files) {
  $bytes = [IO.File]::ReadAllBytes($file)
  if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xef -and $bytes[1] -eq 0xbb -and $bytes[2] -eq 0xbf) { throw "$file contains a UTF-8 BOM." }
  $null = $utf8.GetString($bytes)
  for ($index = 0; $index -lt $bytes.Length; ++$index) {
    if ($bytes[$index] -eq 10 -and ($index -eq 0 -or $bytes[$index - 1] -ne 13)) { throw "$file contains a bare LF." }
    if ($bytes[$index] -eq 13 -and ($index + 1 -ge $bytes.Length -or $bytes[$index + 1] -ne 10)) { throw "$file contains a bare CR." }
  }
  if ($bytes.Length -lt 2 -or $bytes[$bytes.Length - 2] -ne 13 -or $bytes[$bytes.Length - 1] -ne 10) { throw "$file does not end with CRLF." }
}
Write-Output "Post-correction text policy passed for $($files.Count) files."
